/** Compile-time model for the compact binary form. */
public final class BinarySerialization {
  private static final BinarySerialization DISABLED = new BinarySerialization(false, ImmutableList.of());

  private final boolean enabled;
  private final ImmutableList<Attribute> attributes;

  private BinarySerialization(boolean enabled, ImmutableList<Attribute> attributes) {
    this.enabled = enabled;
    this.attributes = attributes;
  }

  public boolean isEnabled() {
    return enabled;
  }

  public ImmutableList<Attribute> getAttributes() {
    return attributes;
  }

  public static BinarySerialization disabled() {
    return DISABLED;
  }

  public static void configure(Multimap<DeclaringPackage, ValueType> values) {
    ArrayList<ValueType> all = new ArrayList<>();
    for (ValueType type : values.values()) collect(type, all);
    if (all.isEmpty()) return;

    ValueType sample = all.get(0);
    if (!sample.constitution.protoclass().environment().hasSerialModule()) return;

    Map<String, ValueType> byName = new HashMap<>();
    for (ValueType type : all) {
      byName.put(((TypeElement) type.element).getQualifiedName().toString(), type);
    }
    Resolver resolver = new Resolver(byName);
    for (ValueType type : all) resolver.resolve(type);
  }

  private static void collect(ValueType type, List<ValueType> all) {
    all.add(type);
    for (ValueType nested : type.nested) collect(nested, all);
  }

  public static final class Attribute {
    private final ValueAttribute attribute;
    private final long nameHigh;
    private final long nameLow;
    private final long shape;
    private final int elementKind;
    private final int secondaryKind;
    private final String elementEnumClass;
    private final String secondaryEnumClass;
    private final String arrayComponentClass;
    private final String nestedImmutableType;
    private final String category;

    Attribute(ValueAttribute attribute, long nameHigh, long nameLow, long shape,
        int elementKind, int secondaryKind, String elementEnumClass,
        String secondaryEnumClass, String arrayComponentClass, String nestedImmutableType,
        String category) {
      this.attribute = attribute;
      this.nameHigh = nameHigh;
      this.nameLow = nameLow;
      this.shape = shape;
      this.elementKind = elementKind;
      this.secondaryKind = secondaryKind;
      this.elementEnumClass = elementEnumClass;
      this.secondaryEnumClass = secondaryEnumClass;
      this.arrayComponentClass = arrayComponentClass;
      this.nestedImmutableType = nestedImmutableType;
      this.category = category;
    }

    public ValueAttribute getAttribute() { return attribute; }
    public String getNameHigh() { return literal(nameHigh); }
    public String getNameLow() { return literal(nameLow); }
    public String getShape() { return literal(shape); }
    public int getElementKind() { return elementKind; }
    public int getSecondaryKind() { return secondaryKind; }
    public String getElementEnumClass() { return elementEnumClass; }
    public String getSecondaryEnumClass() { return secondaryEnumClass; }
    public String getArrayComponentClass() { return arrayComponentClass; }
    public String getNestedImmutableType() { return nestedImmutableType; }
    public boolean isNested() { return category.equals("nested"); }
    public boolean isArray() { return category.equals("array"); }
    public boolean isOptional() { return category.equals("optional"); }
    public boolean isCollection() { return category.equals("collection"); }
    public boolean isMap() { return category.equals("map"); }

    private static String literal(long value) {
      return value == Long.MIN_VALUE ? "0x8000000000000000L" : value + "L";
    }
  }

  private enum State { RESOLVING, ENABLED, DISABLED }

  private static final class Resolver {
    private final Map<String, ValueType> byName;
    private final Map<ValueType, State> states = new HashMap<>();

    Resolver(Map<String, ValueType> byName) {
      this.byName = byName;
    }

    boolean resolve(ValueType type) {
      State state = states.get(type);
      if (state == State.ENABLED) return true;
      if (state == State.DISABLED || state == State.RESOLVING) {
        if (state == State.RESOLVING) disable(type);
        return false;
      }
      states.put(type, State.RESOLVING);

      if (hasConflict(type) || hasRequiredAuxiliary(type)) {
        return disable(type);
      }

      boolean builder = type.isUseBuilder();
      boolean constructor = !builder && type.isUseConstructor();
      if (!builder && !constructor) return disable(type);

      Set<ValueAttribute> constructorArguments = type.getConstructorArguments();
      ArrayList<Attribute> attributes = new ArrayList<>();
      Set<String> identities = new HashSet<>();
      for (ValueAttribute attribute : type.getSettableAttributes()) {
        if (attribute.isAuxiliary()) continue;
        if (constructor && !constructorArguments.contains(attribute)) return disable(type);

        Shape shape = shape(attribute.returnType, attribute, true);
        if (shape == null || (constructor && !shape.constructorSupported)) return disable(type);
        if (shape.nested != null && !resolve(shape.nested)) return disable(type);

        long high = hash(attribute.name(), 0xcbf29ce484222325L);
        long low = hash(attribute.name(), 0x84222325cbf29ce4L);
        String identity = high + ":" + low;
        if ((high == 0L && low == 0L) || !identities.add(identity)) return disable(type);

        attributes.add(new Attribute(attribute, high, low, hash(shape.canonical, 0x9e3779b97f4a7c15L),
            shape.elementKind, shape.secondaryKind, shape.elementEnumClass,
            shape.secondaryEnumClass, shape.arrayComponentClass,
            shape.nested == null ? null : appliedImmutableType(shape.nested, attribute.returnType),
            shape.category));
      }

      type.binary = new BinarySerialization(true, ImmutableList.copyOf(attributes));
      states.put(type, State.ENABLED);
      return true;
    }

    private boolean disable(ValueType type) {
      type.binary = DISABLED;
      states.put(type, State.DISABLED);
      return false;
    }

    private boolean hasRequiredAuxiliary(ValueType type) {
      for (ValueAttribute attribute : type.getSettableAttributes()) {
        if (attribute.isAuxiliary() && attribute.isMandatory()) return true;
      }
      return false;
    }

    private boolean hasConflict(ValueType type) {
      Elements elements = type.constitution.protoclass().environment().processing().getElementUtils();
      Types types = type.constitution.protoclass().environment().processing().getTypeUtils();
      TypeElement dataInput = elements.getTypeElement("java.io.DataInput");
      TypeElement dataOutput = elements.getTypeElement("java.io.DataOutput");
      if (dataInput == null || dataOutput == null) return true;
      TypeElement sourceType = elements.getTypeElement(((TypeElement) type.element).getQualifiedName());
      if (sourceType == null) return true;
      for (ExecutableElement method : ElementFilter.methodsIn(elements.getAllMembers(sourceType))) {
        if (method.getParameters().size() != 1) continue;
        String name = method.getSimpleName().toString();
        TypeMirror parameter = types.erasure(method.getParameters().get(0).asType());
        if (name.equals("writeTo") && types.isSameType(parameter, types.erasure(dataOutput.asType()))) return true;
        if (name.equals("readFrom") && types.isSameType(parameter, types.erasure(dataInput.asType()))) return true;
      }
      return false;
    }

    private Shape shape(TypeMirror mirror, ValueAttribute attribute, boolean topLevel) {
      if (mirror.getKind() == TypeKind.ARRAY) {
        TypeMirror component = ((ArrayType) mirror).getComponentType();
        if (component.getKind() == TypeKind.ARRAY) return null;
        Scalar scalar = scalar(component, false);
        if (scalar == null) return null;
        return new Shape("array(" + scalar.kind + ")", "array", scalar.kind, 0,
            scalar.enumClass, "null", classLiteralType(component), null, false);
      }

      if (mirror.getKind().isPrimitive()) {
        Scalar scalar = scalar(mirror, false);
        return scalar == null ? null : Shape.scalar(scalar, true);
      }
      if (mirror.getKind() != TypeKind.DECLARED) return null;

      DeclaredType declared = (DeclaredType) mirror;
      TypeElement element = (TypeElement) declared.asElement();
      String raw = element.getQualifiedName().toString();
      ValueType nested = byName.get(raw);
      if (nested != null) {
        return new Shape("nested", "nested", 0, 0, "null", "null", "null", nested, false);
      }

      Scalar direct = scalar(mirror, attribute.isNullable());
      if (direct != null) return Shape.scalar(direct, true);

      if ((raw.equals("java.util.SortedSet") || raw.equals("java.util.NavigableSet"))
          && declared.getTypeArguments().size() == 1 && !attribute.isNullable()) {
        Scalar scalar = scalar(declared.getTypeArguments().get(0), false);
        if (scalar == null) return null;
        return new Shape("SORTED_SET(" + scalar.kind + ")", "collection", scalar.kind, 0,
            scalar.enumClass, "null", "null", null, false);
      }
      if ((raw.equals("java.util.SortedMap") || raw.equals("java.util.NavigableMap"))
          && declared.getTypeArguments().size() == 2 && !attribute.isNullable()) {
        Scalar key = scalar(declared.getTypeArguments().get(0), false);
        Scalar value = scalar(declared.getTypeArguments().get(1), false);
        if (key == null || value == null) return null;
        return new Shape("SORTED_MAP(" + key.kind + "," + value.kind + ")", "map",
            key.kind, value.kind, key.enumClass, value.enumClass, "null", null, false);
      }

      AttributeTypeKind kind = attribute.typeKind();
      List<? extends TypeMirror> arguments = declared.getTypeArguments();
      if (kind.isOptionalKind()) {
        Scalar scalar;
        if (attribute.isJdkSpecializedOptional()) {
          String specialized = attribute.optionalSpecializedType();
          scalar = scalarForName(specialized, false);
        } else {
          if (arguments.size() != 1) return null;
          if (arguments.size() != 1) return null;
          scalar = scalar(arguments.get(0), false);
        }
        if (scalar == null) return null;
        return new Shape("optional(" + scalar.kind + ")", "optional", scalar.kind, 0,
            scalar.enumClass, "null", "null", null, true);
      }
      if (kind.isCollectionKind()) {
        if (attribute.isNullable() || arguments.size() != 1) return null;
        Scalar scalar = scalar(arguments.get(0), false);
        if (scalar == null) return null;
        boolean constructorSupported = kind.isList() || kind.isSet();
        return new Shape(kind.name() + "(" + scalar.kind + ")", "collection", scalar.kind, 0,
            scalar.enumClass, "null", "null", null, constructorSupported);
      }
      if (kind.isMappingKind()) {
        if (attribute.isNullable() || arguments.size() != 2) return null;
        Scalar key = scalar(arguments.get(0), false);
        Scalar value = scalar(arguments.get(1), false);
        if (key == null || value == null) return null;
        boolean constructorSupported = kind.isPlainMapKind() || kind.isSortedMap();
        return new Shape(kind.name() + "(" + key.kind + "," + value.kind + ")", "map",
            key.kind, value.kind, key.enumClass, value.enumClass, "null", null,
            constructorSupported);
      }
      return null;
    }

    private Scalar scalar(TypeMirror mirror, boolean nullable) {
      if (mirror.getKind().isPrimitive()) return scalarForName(mirror.toString(), false);
      if (mirror.getKind() != TypeKind.DECLARED) return null;
      TypeElement element = (TypeElement) ((DeclaredType) mirror).asElement();
      if (element.getKind() == ElementKind.ENUM) {
        return new Scalar(nullable ? 20 : 18, element.getQualifiedName() + ".class");
      }
      Scalar scalar = scalarForName(element.getQualifiedName().toString(), nullable);
      return scalar;
    }

    private Scalar scalarForName(String name, boolean nullable) {
      switch (name) {
        case "boolean": return new Scalar(1, "null");
        case "byte": return new Scalar(2, "null");
        case "short": return new Scalar(3, "null");
        case "int": return new Scalar(4, "null");
        case "long": return new Scalar(5, "null");
        case "char": return new Scalar(6, "null");
        case "float": return new Scalar(7, "null");
        case "double": return new Scalar(8, "null");
        case "java.lang.Boolean": return new Scalar(9, "null");
        case "java.lang.Byte": return new Scalar(10, "null");
        case "java.lang.Short": return new Scalar(11, "null");
        case "java.lang.Integer": return new Scalar(12, "null");
        case "java.lang.Long": return new Scalar(13, "null");
        case "java.lang.Character": return new Scalar(14, "null");
        case "java.lang.Float": return new Scalar(15, "null");
        case "java.lang.Double": return new Scalar(16, "null");
        case "java.lang.String": return new Scalar(nullable ? 19 : 17, "null");
        default: return null;
      }
    }

    private String appliedImmutableType(ValueType nested, TypeMirror declared) {
      StringBuilder builder = new StringBuilder(nested.constitution.typeImmutable().absoluteRaw());
      if (declared.getKind() == TypeKind.DECLARED) {
        List<? extends TypeMirror> arguments = ((DeclaredType) declared).getTypeArguments();
        if (!arguments.isEmpty()) {
          builder.append('<');
          for (int i = 0; i < arguments.size(); i++) {
            if (i > 0) builder.append(", ");
            builder.append(arguments.get(i));
          }
          builder.append('>');
        }
      }
      return builder.toString();
    }
  }

  private static final class Scalar {
    final int kind;
    final String enumClass;
    Scalar(int kind, String enumClass) {
      this.kind = kind;
      this.enumClass = enumClass;
    }
  }

  private static final class Shape {
    final String canonical;
    final String category;
    final int elementKind;
    final int secondaryKind;
    final String elementEnumClass;
    final String secondaryEnumClass;
    final String arrayComponentClass;
    final ValueType nested;
    final boolean constructorSupported;

    Shape(String canonical, String category, int elementKind, int secondaryKind,
        String elementEnumClass, String secondaryEnumClass, String arrayComponentClass,
        ValueType nested, boolean constructorSupported) {
      this.canonical = canonical;
      this.category = category;
      this.elementKind = elementKind;
      this.secondaryKind = secondaryKind;
      this.elementEnumClass = elementEnumClass;
      this.secondaryEnumClass = secondaryEnumClass;
      this.arrayComponentClass = arrayComponentClass;
      this.nested = nested;
      this.constructorSupported = constructorSupported;
    }

    static Shape scalar(Scalar scalar, boolean constructorSupported) {
      return new Shape("scalar(" + scalar.kind + ")", "scalar", scalar.kind, 0,
          scalar.enumClass, "null", "null", null, constructorSupported);
    }
  }

  private static String classLiteralType(TypeMirror mirror) {
    return mirror.toString() + ".class";
  }

  private static long hash(String value, long seed) {
    long hash = seed;
    for (int i = 0; i < value.length(); i++) {
      hash ^= value.charAt(i);
      hash *= 0x100000001b3L;
      hash ^= hash >>> 32;
    }
    return hash;
  }
}
package org.immutables.serial;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.DataOutput;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.lang.reflect.Array;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** Runtime support for compact binary forms generated by the value processor. */
public final class Binary {
  private static final int MAGIC = 0x494D4231;

  public static final int BOOLEAN = 1;
  public static final int BYTE = 2;
  public static final int SHORT = 3;
  public static final int INT = 4;
  public static final int LONG = 5;
  public static final int CHAR = 6;
  public static final int FLOAT = 7;
  public static final int DOUBLE = 8;
  public static final int BOXED_BOOLEAN = 9;
  public static final int BOXED_BYTE = 10;
  public static final int BOXED_SHORT = 11;
  public static final int BOXED_INT = 12;
  public static final int BOXED_LONG = 13;
  public static final int BOXED_CHAR = 14;
  public static final int BOXED_FLOAT = 15;
  public static final int BOXED_DOUBLE = 16;
  public static final int STRING = 17;
  public static final int ENUM = 18;
  public static final int NULLABLE_STRING = 19;
  public static final int NULLABLE_ENUM = 20;

  private Binary() {}

  /** Implemented by generated immutable values that have a compact binary form. */
  public interface Value {
    void writeTo(DataOutput output) throws IOException;
  }

  public static Writer writer(DataOutput output) throws IOException {
    return new Writer(output);
  }

  public static Reader reader(DataInput input) throws IOException {
    return new Reader(input);
  }

  public static final class Writer {
    private final DataOutput output;
    private FieldOutput active;

    private Writer(DataOutput output) throws IOException {
      this.output = output;
      output.writeInt(MAGIC);
    }

    public FieldOutput field(long nameHigh, long nameLow, long shape) {
      if (active != null) {
        throw new IllegalStateException("Previous binary field has not been finished");
      }
      active = new FieldOutput(this, nameHigh, nameLow, shape);
      return active;
    }

    public void finish() throws IOException {
      if (active != null) {
        throw new IllegalStateException("Binary field has not been finished");
      }
      output.writeLong(0L);
      output.writeLong(0L);
    }

    private void finish(FieldOutput field) throws IOException {
      if (active != field) {
        throw new IllegalStateException("Binary field is not active");
      }
      byte[] payload = field.bytes.toByteArray();
      output.writeLong(field.nameHigh);
      output.writeLong(field.nameLow);
      output.writeLong(field.shape);
      output.writeInt(payload.length);
      output.write(payload);
      active = null;
    }
  }

  public static final class FieldOutput {
    private final Writer writer;
    private final long nameHigh;
    private final long nameLow;
    private final long shape;
    private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    private final DataOutputStream output = new DataOutputStream(bytes);
    private boolean finished;

    private FieldOutput(Writer writer, long nameHigh, long nameLow, long shape) {
      this.writer = writer;
      this.nameHigh = nameHigh;
      this.nameLow = nameLow;
      this.shape = shape;
    }

    public DataOutput output() {
      return output;
    }

    public void finish() throws IOException {
      if (finished) {
        throw new IllegalStateException("Binary field already finished");
      }
      finished = true;
      output.flush();
      writer.finish(this);
    }
  }

  public static final class Reader {
    private final DataInput input;
    private long nameHigh;
    private long nameLow;
    private long shape;
    private DataInputStream field;
    private boolean ended;

    private Reader(DataInput input) throws IOException {
      this.input = input;
      if (input.readInt() != MAGIC) {
        throw new IOException("Invalid compact binary header");
      }
    }

    public boolean next() throws IOException {
      if (ended) {
        return false;
      }
      nameHigh = input.readLong();
      nameLow = input.readLong();
      if (nameHigh == 0L && nameLow == 0L) {
        ended = true;
        field = null;
        return false;
      }
      shape = input.readLong();
      int length = input.readInt();
      if (length < 0) {
        throw new IOException("Negative compact binary field length");
      }
      byte[] payload = new byte[length];
      input.readFully(payload);
      field = new DataInputStream(new ByteArrayInputStream(payload));
      return true;
    }

    public boolean matches(long expectedHigh, long expectedLow, long expectedShape) {
      return nameHigh == expectedHigh && nameLow == expectedLow && shape == expectedShape;
    }

    public DataInput input() {
      if (field == null) {
        throw new IllegalStateException("No current binary field");
      }
      return field;
    }

    public void complete() throws TypeMismatchException {
      try {
        if (field == null || field.available() != 0) {
          throw new TypeMismatchException();
        }
      } catch (IOException ex) {
        throw new TypeMismatchException();
      }
    }
  }

  public static final class TypeMismatchException extends Exception {
    private static final long serialVersionUID = 1L;
  }

  public static void writeScalar(DataOutput output, int kind, Object value) throws IOException {
    switch (kind) {
      case BOOLEAN: output.writeBoolean((Boolean) value); return;
      case BYTE: output.writeByte((Byte) value); return;
      case SHORT: output.writeShort((Short) value); return;
      case INT: output.writeInt((Integer) value); return;
      case LONG: output.writeLong((Long) value); return;
      case CHAR: output.writeChar((Character) value); return;
      case FLOAT: output.writeFloat((Float) value); return;
      case DOUBLE: output.writeDouble((Double) value); return;
      case BOXED_BOOLEAN:
      case BOXED_BYTE:
      case BOXED_SHORT:
      case BOXED_INT:
      case BOXED_LONG:
      case BOXED_CHAR:
      case BOXED_FLOAT:
      case BOXED_DOUBLE:
        output.writeBoolean(value != null);
        if (value != null) writeScalar(output, kind - 8, value);
        return;
      case STRING:
        writeString(output, (String) value);
        return;
      case NULLABLE_STRING:
        output.writeBoolean(value != null);
        if (value != null) writeString(output, (String) value);
        return;
      case ENUM:
        writeString(output, ((Enum<?>) value).name());
        return;
      case NULLABLE_ENUM:
        output.writeBoolean(value != null);
        if (value != null) writeString(output, ((Enum<?>) value).name());
        return;
      default:
        throw new IOException("Unsupported compact binary scalar kind " + kind);
    }
  }

  public static Object readScalar(DataInput input, int kind, Class<?> enumType)
      throws IOException, TypeMismatchException {
    try {
      switch (kind) {
        case BOOLEAN: return input.readBoolean();
        case BYTE: return input.readByte();
        case SHORT: return input.readShort();
        case INT: return input.readInt();
        case LONG: return input.readLong();
        case CHAR: return input.readChar();
        case FLOAT: return input.readFloat();
        case DOUBLE: return input.readDouble();
        case BOXED_BOOLEAN:
        case BOXED_BYTE:
        case BOXED_SHORT:
        case BOXED_INT:
        case BOXED_LONG:
        case BOXED_CHAR:
        case BOXED_FLOAT:
        case BOXED_DOUBLE:
          return input.readBoolean() ? readScalar(input, kind - 8, null) : null;
        case STRING: return readString(input);
        case NULLABLE_STRING: return input.readBoolean() ? readString(input) : null;
        case ENUM: return readEnum(input, enumType);
        case NULLABLE_ENUM: return input.readBoolean() ? readEnum(input, enumType) : null;
        default: throw new TypeMismatchException();
      }
    } catch (EOFException ex) {
      throw ex;
    } catch (ClassCastException | IllegalArgumentException ex) {
      throw new TypeMismatchException();
    }
  }

  public static void writeArray(DataOutput output, int kind, Object array) throws IOException {
    int length = Array.getLength(array);
    output.writeInt(length);
    for (int i = 0; i < length; i++) {
      writeScalar(output, kind, Array.get(array, i));
    }
  }

  public static Object readArray(DataInput input, int kind, Class<?> componentType, Class<?> enumType)
      throws IOException, TypeMismatchException {
    int length = readLength(input);
    Object array = Array.newInstance(componentType, length);
    for (int i = 0; i < length; i++) {
      try {
        Array.set(array, i, readScalar(input, kind, enumType));
      } catch (IllegalArgumentException ex) {
        throw new TypeMismatchException();
      }
    }
    return array;
  }

  public static void writeCollection(DataOutput output, int kind, Iterable<?> values) throws IOException {
    ArrayList<Object> copy = new ArrayList<>();
    for (Object value : values) copy.add(value);
    output.writeInt(copy.size());
    for (Object value : copy) writeScalar(output, kind, value);
  }

  public static List<Object> readCollection(DataInput input, int kind, Class<?> enumType)
      throws IOException, TypeMismatchException {
    int size = readLength(input);
    ArrayList<Object> values = new ArrayList<>(size);
    for (int i = 0; i < size; i++) values.add(readScalar(input, kind, enumType));
    return values;
  }

  public static void writeMap(DataOutput output, int keyKind, int valueKind,
      Iterable<? extends java.util.Map.Entry<?, ?>> entries) throws IOException {
    ArrayList<java.util.Map.Entry<?, ?>> copy = new ArrayList<>();
    for (java.util.Map.Entry<?, ?> entry : entries) copy.add(entry);
    output.writeInt(copy.size());
    for (java.util.Map.Entry<?, ?> entry : copy) {
      writeScalar(output, keyKind, entry.getKey());
      writeScalar(output, valueKind, entry.getValue());
    }
  }

  public static List<Object> readMap(DataInput input, int keyKind, Class<?> keyEnum,
      int valueKind, Class<?> valueEnum) throws IOException, TypeMismatchException {
    int size = readLength(input);
    ArrayList<Object> entries = new ArrayList<>(size * 2);
    for (int i = 0; i < size; i++) {
      entries.add(readScalar(input, keyKind, keyEnum));
      entries.add(readScalar(input, valueKind, valueEnum));
    }
